<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class MedicalTest extends Model { protected $guarded=[]; protected $casts=['synonyms'=>'array','fasting_required'=>'boolean','can_be_outsourced'=>'boolean','is_active'=>'boolean']; public function category(){return $this->belongsTo(MedicalCategory::class,'medical_category_id');} public function specimenType(){return $this->belongsTo(SpecimenType::class);} public function collectionTube(){return $this->belongsTo(CollectionTube::class);} public function materialRequirements(){return $this->hasMany(TestMaterialRequirement::class)->orderBy('preference');} public function groups(){return $this->belongsToMany(AnalysisGroup::class,'group_test_items')->withPivot('sort_order')->withTimestamps();} public function parameters(){return $this->hasMany(TestParameter::class)->orderBy('sort_order');} public function laboratoryTest(){return $this->hasOne(LaboratoryTest::class);} }
